        let args = message as! [Any?]
        let onArg = args[0] as! Bool
        do {
          try api.setBackdropBlur(on: onArg)
          reply(wrapResult(nil))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      setBackdropBlurChannel.setMessageHandler(nil)
    }
    /// La rotación de la franja (IOS-48), en JSON: `{"ads": [{"name", "dir", "fps"}],
    /// "slots": [{"name", "loops"}]}`. `dir` es un directorio de PNG RGBA de 1920×108
    /// dentro de `Documents/ads/`; en lugar de `dir`, `frames` es la lista de PNG de cada
    /// fotograma, repetidos, relativos a `Documents/ads/` (el paquete del VPS, IOS-49).
    /// Los anuncios que no están en `slots` se cargan para `setAdOverride`. Arranca en
    /// este instante. Devuelve "" o el error.
    let setAdPlaylistChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.football_ai_capture.RigHostApi.setAdPlaylist\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      setAdPlaylistChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let jsonArg = args[0] as! String
        do {
          let result = try api.setAdPlaylist(json: jsonArg)
          reply(wrapResult(result))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      setAdPlaylistChannel.setMessageHandler(nil)
    }
    /// La última miniatura JPEG de 640×360 (IOS-64): `left`, `right` o `program`. Vacía si
    /// todavía no hay.
    let thumbnailChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.football_ai_capture.RigHostApi.thumbnail\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      thumbnailChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let nameArg = args[0] as! String
        do {
          let result = try api.thumbnail(name: nameArg)
          reply(wrapResult(result))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      thumbnailChannel.setMessageHandler(nil)
    }
    /// Un anuncio ya cargado que se cuela desde ahora `loops` vueltas; nombre vacío lo quita.
    let setAdOverrideChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.football_ai_capture.RigHostApi.setAdOverride\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      setAdOverrideChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let nameArg = args[0] as! String
        let loopsArg = args[1] as! Int64
        do {
          try api.setAdOverride(name: nameArg, loops: loopsArg)
          reply(wrapResult(nil))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      setAdOverrideChannel.setMessageHandler(nil)
    }
    /// Pasa el MP4 de `path` en el programa (ADR 0027, decisión 4): a pantalla completa por
    /// encima del gráfico y con su sonido en lugar del micro, desde dentro de `leadMs`. `id`
    /// es la reproducción: vuelve en `onVideoEnded` al acabar. Quita el que sonara.
    /// Devuelve "" o el error (sin vídeo que leer, códec que no se decodifica…).
    let playVideoChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.football_ai_capture.RigHostApi.playVideo\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      playVideoChannel.setMessageHandler { message, reply in
        let args = message as! [Any?]
        let idArg = args[0] as! Int64
        let pathArg = args[1] as! String
        let leadMsArg = args[2] as! Int64
        Task { @MainActor in
          do {
            let result = try await api.playVideo(id: idArg, path: pathArg, leadMs: leadMsArg)
            reply(wrapResult(result))
          } catch {
            reply(wrapError(error))
          }
        }
      }
    } else {
      playVideoChannel.setMessageHandler(nil)
    }
    /// Quita el vídeo que suena, si suena: vuelven el programa y el micro.
    let stopVideoChannel = FlutterBasicMessageChannel(name: "dev.flutter.pigeon.football_ai_capture.RigHostApi.stopVideo\(channelSuffix)", binaryMessenger: binaryMessenger, codec: codec)
    if let api = api {
      stopVideoChannel.setMessageHandler { _, reply in
        do {
          try api.stopVideo()
          reply(wrapResult(nil))
        } catch {
          reply(wrapError(error))
        }
      }
    } else {
      stopVideoChannel.setMessageHandler(nil)
    }
  }
}

/// Generated protocol from Pigeon that represents Flutter messages that can be called from Swift.
protocol RigFlutterApiProtocol {
  /// Progreso del banco en marcha, para la página: fracción 0-1 y una línea de detalle.
  @MainActor func onBenchProgress(name nameArg: String, fraction fractionArg: Double, detail detailArg: String) async throws
}
class RigFlutterApi: RigFlutterApiProtocol {
  private let binaryMessenger: FlutterBinaryMessenger
  private let messageChannelSuffix: String
  init(binaryMessenger: FlutterBinaryMessenger, messageChannelSuffix: String = "") {
    self.binaryMessenger = binaryMessenger
    self.messageChannelSuffix = messageChannelSuffix.count > 0 ? ".\(messageChannelSuffix)" : ""
  }
  var codec: RigApiPigeonCodec {
    return RigApiPigeonCodec.shared
  }
  /// Progreso del banco en marcha, para la página: fracción 0-1 y una línea de detalle.
  @MainActor func onBenchProgress(name nameArg: String, fraction fractionArg: Double, detail detailArg: String) async throws {
    return try await withCheckedThrowingContinuation { continuation in
      let channelName: String = "dev.flutter.pigeon.football_ai_capture.RigFlutterApi.onBenchProgress\(messageChannelSuffix)"
      let channel = FlutterBasicMessageChannel(name: channelName, binaryMessenger: binaryMessenger, codec: codec)
      channel.sendMessage([nameArg, fractionArg, detailArg] as [Any?]) { response in
        guard let listResponse = response as? [Any?] else {
          continuation.resume(throwing: createConnectionError(withChannelName: channelName))
          return
        }
        if listResponse.count > 1 {
          let code: String = listResponse[0] as! String
          let message: String? = nilOrValue(listResponse[1])
          let details: String? = nilOrValue(listResponse[2])
          continuation.resume(throwing: PigeonError(code: code, message: message, details: details))
        } else {
          continuation.resume()
        }
      }
    }
  }
}
